head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF10004";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10004.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const v_group = (scwin.openerScwin()["cfi_cd"] && (scwin.openerScwin()["cfi_cd"]).getValue ? (scwin.openerScwin()["cfi_cd"]).getValue() : (scwin.openerComp("cfi_cd").getValue ? scwin.opener().getComponentById("cfi_cd").getValue() : ''));
        if (v_group.length === 6 && v_group.substring(0, 2) === "EU") {
            $('#slc_cbAttr1').find('option[value="' + v_group.substring(2, 3) + '"]').attr("selected", true);
            $('#slc_cbAttr2').find('option[value="' + v_group.substring(3, 4) + '"]').attr("selected", true);
            $('#slc_cbAttr3').find('option[value="' + v_group.substring(4, 5) + '"]').attr("selected", true);
            $('#slc_cbAttr4').find('option[value="' + v_group.substring(5, 6) + '"]').attr("selected", true);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10004.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendForm_onclick = function(e){
    try {
        scwin.send_form('__self.form')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10004.btn_sendForm_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.send_form = function (fm) {
    fm = (document.JLDINF10004 || { elements: [] });
    let CFIcode;
    CFIcode = "EU";
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr1').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr2').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr3').getValue();
    CFIcode = CFIcode + $c.util.getComponent('slc_cbAttr4').getValue();
    ((scwin.opener().getComponentById("cfi_cd")) && (scwin.opener().getComponentById("cfi_cd")).setValue ? (scwin.opener().getComponentById("cfi_cd")).setValue(CFIcode) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "cfi_cd"), void (CFIcode)));
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};

/**
 * @method
 * @name openerComp
 * @description 부모 화면 컴포넌트(as-is opener.document.<폼>.<필드>). 부모·컴포넌트가 없으면 빈 객체(메서드 존재 검사로 건너뛴다)
 * @param {*} id 부모 화면 컴포넌트 id
 * @returns {Object} 컴포넌트 또는 {}
 * @hidden N
 */
scwin.openerComp = function (id) {
    return scwin.opener().getComponentById(id) || {};
};
